import { Card, CardContent, CardHeader, CardTitle, ListRow, Badge } from "@godxjp/ui/data-display";
import { Button } from "@godxjp/ui/general";
import { Smartphone } from "lucide-react";
import { Flex } from "@godxjp/ui/layout";

// The three scenarios below are three CARDS on one page, so they are wrapped in a Flex — the gap
// between sibling cards belongs to the stack, never to the cards (audit: sibling-cards-need-flex).
<Flex direction="col" gap="lg">
<Card>
  <CardHeader>
    <CardTitle>アクティブなセッション</CardTitle>
  </CardHeader>
  <CardContent flush>
    <ListRow
      leading={<Smartphone aria-hidden="true" className="size-4" />}
      title="iPhone 15 · Tokyo"
      description="最終アクセス 2分前"
      trailing={<Badge status="active" />}
    />
    <ListRow
      leading={<Smartphone aria-hidden="true" className="size-4" />}
      title="MacBook Pro · Osaka"
      description="最終アクセス 3日前"
      trailing={<Button size="xs" variant="outline">ログアウト</Button>}
    />
  </CardContent>
</Card>

// Notifications — unread dot + emphasized surface, wrapping title, two inline actions
<Card>
  <CardContent flush>
    <ListRow
      unread
      align="start"
      overflow="wrap"
      title="組織「グローバル・トランスフォーメーション推進本部」への招待が届いています"
      description="2026-07-30 09:12 JST"
      trailing={
        <>
          <Button size="xs" variant="ghost">既読にする</Button>
          <Button size="xs" variant="outline">開く</Button>
        </>
      }
    />
    <ListRow unread={false} align="start" overflow="wrap" title="請求書が発行されました" description="2026-07-28 18:40 JST" />
  </CardContent>
</Card>

// A list of LINKS — `as="li"` gives the list item, `asChild` gives the whole-row link,
// and the item carries the divider. Never wrap the row in your own <li>, and never reach for a
// raw <ul>: `marker="none"` is the semantic list container (no bullet, no indent, gap token).
<Card>
  <CardContent flush>
    <Flex as="ul" marker="none" direction="col" gap="none">
      {projects.map((project) => (
        <ListRow key={project.key} as="li" asChild title={project.name} description={project.key}>
          <Link href={`/projects/${project.key}`} />
        </ListRow>
      ))}
    </Flex>
  </CardContent>
</Card>
</Flex>
